export const englishChapters=[{"id": 1, "title": "Six Years of School Bells", "region": "TAIWAN / Shiyu High School · Ages 12–18", "symbol": "strict schedules and rules", "pages": ["From age 12 to 18, I spent six years at Shiyu High School, including time as a boarding student.", "Shiyu was known for its military-style education. It taught me self-discipline.", "I also had ADHD as a child. It gradually faded as I grew older, but my mischievous streak was part of who I was.", "I helped plan several events. Before graduating, I also served as vice chair of the graduation ceremony planning committee."], "result": "In high school, English felt like a spell I could never decipher. At the time, I chose to give up.", "bridge": ""}, {"id": 2, "title": "The World Beyond the Screen", "region": "TAIWAN → JAPAN / Japanese and Departure", "symbol": "Japanese and an unfamiliar environment", "pages": ["Drawn to Japan, I passed the JLPT N3 Japanese test before finishing high school.", "I decided against majoring in Japanese. By my second year of high school, I was planning to study in Japan after graduation. I am grateful for my family's support!", "In my final year, I switched to commuting. I wanted to experience working life early and help my family, so I started working part-time!"], "result": "After passing JLPT N3, I went to a language school in Tokyo.", "bridge": "While studying, I tried different part-time jobs in food service, sales, and events."}, {"id": 3, "title": "Japan: The First Door", "region": "JAPAN / First Year of University", "symbol": "the application and interview process", "pages": ["After working hard and receiving several offers, I chose the business school at Kokushikan University in Tokyo. As soon as I enrolled, I applied for a part-time Specialist role at Apple.", "I also worked to keep up my grades and received scholarships for three consecutive years, totaling JPY 1 million.", "I passed the first three interview stages, but ultimately was not hired. Around the same time, I met someone from another country who spoke Chinese, Japanese, and English. That planted the seed for returning to English later."], "result": "I was not hired for the Apple Specialist role, but I was not sad about it. I wanted to keep improving myself.", "bridge": ""}, {"id": 4, "title": "Turning a Proposal into an Opportunity", "region": "JAPAN / Campus Bubble Tea Shop", "symbol": "turning an idea into daily operations", "pages": ["By chance, I met a young man selling bubble tea from a small window in the university cafeteria. I shared operational ideas and a proposal, and told him I wanted to take part in a real business.", "After working through it together, we figured out the process of opening a shop!"], "result": "After being hired as a manager, I began learning small-shop management, daily operations, and marketing analysis.", "bridge": "I helped open and operate a second bubble tea shop in a shopping district."}, {"id": 5, "title": "Opening on the Shopping Street", "region": "JAPAN / Kyodo Shopping District", "symbol": "staffing, purchasing, and shop operations", "pages": ["In the Kyodo shopping district, I helped open and operate a bubble tea shop.", "Scheduling, purchasing, POS, payments, finances, and staff matters were all part of my work. It was harder than I had imagined, with differences in Japanese business culture, language barriers, and supplier coordination.", "But I believed my team and I could do it."], "result": "After helping open the shop, I began dealing with its everyday operations.", "bridge": "The decision to join delivery platforms early would later help the shop through a worldwide crisis."}, {"id": 6, "title": "After the Craze Faded", "region": "JAPAN / Bubble Tea · Changing Demand", "symbol": "changes in the market and seasons", "pages": ["After opening, we faced seasonal changes and shifts in demand. Hot bubble tea was not a common preference in Japan, and our revenue fell in winter.", "We had to adjust what we sold to match what customers wanted.", "I thought Uber Eats had a good business model and decided to bring delivery platforms into the shop early."], "result": "We kept adjusting how we operated, trying approaches beyond our original plan.", "bridge": "We opened in August, and the year was drawing to a close. It should have been a time for Christmas and New Year celebrations, but an unknown disruption was approaching."}, {"id": 7, "title": "The Pandemic Redrew the Map", "region": "JAPAN / Operating Through the Pandemic", "symbol": "disrupted plans", "pages": ["The pandemic hit food service. We had to stop serving customers inside the shop, disrupting our operating plans.", "As we adapted to the policies, I also looked for other income. The good news was that we were the first shop on our shopping street to introduce Uber Eats. Revenue fell short of expectations, but we slowly built up customer reviews.", "University classes moved online during this period. The Japanese government also provided students with JPY 100,000 to buy computers."], "result": "Joining delivery platforms early helped the bubble tea shop survive the pandemic.", "bridge": "Then I spotted another business opportunity. This time, I would be studying computer components."}, {"id": 8, "title": "Starting with Components", "region": "JAPAN / Custom PC Studio", "symbol": "component selection and technical knowledge", "pages": ["Before my second year of university, I took my JPY 100,000 grant to Akihabara. I noticed demand for custom PCs among Chinese-speaking residents in Japan. Language and technical barriers could leave them buying expensive prebuilt computers instead.", "I started teaching myself PC assembly and studying component performance and configurations. In the process, I found a new business model.", "I later founded a PC studio and began selling custom-built computers online."], "result": "PC assembly became another part of my businesses in Japan, and the scale of the business kept growing.", "bridge": "Still, not every business I tried succeeded."}, {"id": 9, "title": "A Side Quest That Did Not Succeed", "region": "JAPAN / ALT Shopping Service", "symbol": "positioning, customer acquisition, and logistics", "pages": ["I also ran a shopping service brand called ALT.", "Brand positioning, finding customers, and setting service fees were all challenges.", "International logistics and taxes added more difficulties. In the end, this business venture did not succeed."], "result": "ALT was an unsuccessful attempt in my entrepreneurial journey.", "bridge": "Meanwhile, on the food-service side, we were also trying another product."}, {"id": 10, "title": "A New Mission in the Same Kitchen", "region": "JAPAN / Taiwanese Chicken Delivery Brand", "symbol": "different products and customer groups", "pages": ["Alongside bubble tea, we developed a Taiwanese fried chicken delivery brand. I found that one shop could operate on two or even three delivery platforms.", "Using our existing operating resources, we began serving different products and customer groups to expand our market share.", "The same kitchen had a new mission. Diversifying also gave us more than one source of income."], "result": "Running a fried chicken delivery brand became another part of my food-service experience.", "bridge": "Meanwhile, the PC studio was also adjusting its brand direction."}, {"id": 11, "title": "The Studio Evolves", "region": "JAPAN / High-End Custom PC Studio", "symbol": "balancing coursework and multiple businesses", "pages": ["As the PC studio grew, I began adjusting its branding, marketing, and service.", "The business gradually shifted toward the high-end custom PC market.", "By my final year, I also had to balance the businesses with my university thesis on the metaverse and NFTs."], "result": "The studio developed from its initial assembly business toward the high-end custom market.", "bridge": "After graduating, I chose to sell the PC business, which had accumulated 1,800 WeChat customers."}, {"id": 12, "title": "Moving On from What I Built", "region": "JAPAN / Selling the Business · Moving On", "symbol": "what I had built and what came next", "pages": ["After graduating, I sold the PC business and prepared to bring this chapter of life in Japan to a close.", "During my time living, studying, and building businesses in Japan, I worked in food service, campus retail, multiple delivery brands, PC assembly, and e-commerce. I also introduced Korean fried chicken to the campus for the first time.", "Together, all of my businesses generated more than JPY 100 million in cumulative revenue over approximately three years.", "While writing my thesis, I drew on many sources from Western countries. That later became part of my reason for deciding to study in the United States."], "result": "After selling the PC business, I closed this chapter of my life in Japan.", "bridge": "Before going to the United States, though, I first went to Cebu in the Philippines to start learning English again."}, {"id": 13, "title": "Six Months in Cebu", "region": "PHILIPPINES / Cebu · Six Months", "symbol": "starting English again", "pages": ["After leaving Japan, I spent six months at a language school in Cebu, in the Philippines.", "I returned to the English I had given up on in high school.", "Over those six months, I started from scratch and gradually rebuilt my English."], "result": "After six months of language school in Cebu, I returned to Taiwan. I still had military service to complete.", "bridge": ""}, {"id": 14, "title": "Back in Taiwan, into the Barracks", "region": "TAIWAN / Military Service", "symbol": "military routines and daily life", "pages": ["After returning to Taiwan, I entered the military to complete my service.", "As I mentioned earlier, that mischievous streak stayed with me. I was still playful in the military.", "I also got along well with my squad leader and had a good time during my service."], "result": "Military service in Taiwan was another chapter before going to the United States.", "bridge": "Before studying abroad, I also had to prepare for IELTS and my applications."}, {"id": 15, "title": "Before Leaving for America", "region": "TAIWAN → USA / Preparing to Study Abroad", "symbol": "exams and preparations to study abroad", "pages": ["To pursue a master's degree in the United States, I prepared for IELTS and my applications.", "I received offers from several schools and eventually chose supply chain management.", "One school in Minnesota was incredibly cold, one in Arizona was incredibly hot, and the University of Southern California was incredibly expensive.", "I chose ASU, also seeing potential in Arizona's development."], "result": "Before departure, my AIT interview appointment was canceled at one point. In the end, I still made it in time to enroll.", "bridge": "From shops and a studio in Japan, my path led to graduate school in Arizona."}, {"id": 16, "title": "A Graduate Student in the Desert", "region": "USA / ASU · W. P. Carey", "symbol": "supply chain coursework and projects", "pages": ["I studied for a Master of Science in Supply Chain Management at ASU's W. P. Carey School of Business.", "Purchasing, supplier coordination, and operations from my shops and e-commerce businesses became practical experience I brought into the classroom.", "During this time, I worked on a supply chain capstone with Moses Lake Industries, analyzing opportunities for improvement. I also started exploring vibe coding and building models and products.", "I graduated in May 2026. I was also fortunate to meet an experienced professional working at the forefront of industry development, who gave me a great deal of guidance."], "result": "I completed my master's degree.", "bridge": "Influenced by that guidance in Arizona, I also began researching connections between Taiwan, Japan, and local industries, along with the development of the ecosystem."}, {"id": 17, "title": "From the Classroom into Industry", "region": "USA / Taiwan, Japan, and Arizona Industry", "symbol": "turning research into business understanding", "pages": ["I began researching semiconductor supply chains and cross-border business opportunities connecting Taiwan, Japan, and Arizona.", "Through networking events and industry conversations, I encountered questions beyond the classroom and built many connections.", "Arizona Chip Journey is a research and project direction I continue to develop."], "result": "These research efforts and projects became evidence of my abilities during my job search. Later, I received an Account Manager offer from TOK's U.S. subsidiary in the semiconductor industry.", "bridge": ""}, {"id": 18, "title": "The Next Chapter Is Still Unwritten", "region": "NEXT CHAPTER / As of October 19, 2026", "symbol": "work authorization and a life transition", "pages": ["I received a formal offer, accepted it, and waited for my work authorization.", "My work authorization application was denied because of a filing-timing mistake. I received the result five months later. The offer was withdrawn, and I never actually started the job.", "My next plans include returning to Taiwan, and I have also thought about going back to Tokyo. Plans cannot always keep up with change. I will adapt and deal with what comes."], "result": "This story is still continuing. I am only 27, and the journey is not over.", "bridge": "I am Jarvis Lin. Next, I hope we can talk about what I could bring to your team."}];
